cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get product details for each item
for (const item of items) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(item.product_id);
  if (product) {
    console.log('\n=== PRODUCT:', product.name, '===');
    console.log('product_id:', product.product_id);
    console.log('category:', product.category);
    console.log('subcategory:', product.subcategory);
    console.log('brand:', product.brand);
    console.log('description:', product.description);
    console.log('specs:', product.specs_json);
  }
  // Also check rt_variants for the specific item
  if (item.item_id) {
    const variant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get(item.item_id);
    if (variant) {
      console.log('\n=== VARIANT ===');
      console.log(JSON.stringify(variant, null, 2));
    }
  }
}
"
